sqlMap.select:
SELECT SP.CODE_NO EMP_TYPE_CODE, SY.CONTENT EMP_TYPE_NAME FROM SY_CODE T, SY_CODE_PARAM SP, SY_GLOBAL_NAME SY WHERE T.CODE_NO = SP.CODE_NO AND T.PARENT_CODE_NO = '1368' AND SP.CPNY_ID = #interCpnyID:VARCHAR# AND T.CODE_NO = SY.NO(+) AND SY.LANGUAGE(+) = #interLanguage:VARCHAR# AND T.ACTIVITY = 1 AND SP.ACTIVITY = 1 AND EXISTS (SELECT * FROM hr_job_type_setup a WHERE CPNY_ID =#interCpnyID:VARCHAR# AND a.jobtype_no = SP.CODE_NO
)
ORDER BY T.ORDERNO
